# Shared resource to simulate the busy state of the channel

def is_channel_busy():##Used for carrier sensing the medium for 2 secs
    print("sender CS")
    received_signal = receive_signal_0(2)
    return bool(received_signal)

def send_audio(message):##Used for sending the data_bits using audio medium and we added # for reducing bit errors
    bit_sequence = "######" + message + "######"

    p = pyaudio.PyAudio()
    stream = p.open(format=FORMAT, channels=CHANNELS, rate=FS, output=True, frames_per_buffer=CHUNK)

    t = np.linspace(0, DURATION_PER_BIT, int(FS * DURATION_PER_BIT), endpoint=False)


    for bit in bit_sequence:
        if bit == '0':
       
            tone = 0.5 * np.sin(2 * np.pi * F_0 * t)
        elif bit == '#':

            tone = 0.5 * np.sin(2 * np.pi * F_NULL * t)
        else:
       
            tone = 0.5 *np.sin(2 * np.pi * F_1 * t)
       
        tone = tone.astype(np.float32)
        stream.write(tone.tobytes())

        tone = 0.0 * np.sin(2 * np.pi * 500 * t)
        tone = tone.astype(np.float32)
        stream.write(tone.tobytes())

    stream.stop_stream()
    stream.close()
    p.terminate()

class Node: ##We are using Class Node for initialization , and for handling multiple nodes
    def __init__(self, node_id, messages, destinations):##For initialization of the Node having node_id,message_queue,destiantion_queue
        self.node_id = node_id
        self.message_queue = Queue()
        self.destination_queue = Queue()
        for msg in messages:
            self.message_queue.put(msg)
        for dest in destinations:
            self.destination_queue.put(dest)
        self.received_messages = []

    def create_mac_header(self, message_type, sender_id, receiver_id, data=None):#creates mac_header distinguishing data_types rts , cts , message
        header = f"{message_type}{format(sender_id, '02b')}{format(receiver_id, '02b')}"
        if data:
            return header + data
        return header

    def send_rts(self, destination_id):#sending rts to destination_id
        if is_channel_busy():
            print(f"Node {self.node_id}: Channel is busy, cannot send RTS.")
            return False
        # sleep_time = random.uniform(1, 5)
        # print(f"wait for {sleep_time} sec before sending RTS")
        # time.sleep(sleep_time)
        rts_message = self.create_mac_header('00', self.node_id, destination_id)
        print(f"Node {self.node_id}: Sending RTS to Node {destination_id}. RTS message: {rts_message}")
        send_audio(rts_message)

        return True

    def receive_rts(self):
        final = receive_signal(4)
        if len(final) == 6:
            first_two_bits = final[:2]
            middle_two_bits = final[2:4]
            last_two_bits = final[-2:]

            print(f"Node {self.node_id}: Received RTS from Node {int(middle_two_bits, 2)}. Checking for collision...")

            if first_two_bits == '00':
                last_two_decimal = int(last_two_bits, 2)

                if last_two_decimal == self.node_id or last_two_decimal == 0: ## Checks if the last two bits matches with the node_id || handled case of broadcasting 
                    if last_two_bits != middle_two_bits and int(middle_two_bits, 2) != self.node_id: ## For Handling the case, not sending cts to current node after receiving the rts 
                        print(f"Node {self.node_id}: No collision detected. Sending CTS.")
                        self.send_cts(int(middle_two_bits, 2))
                        # time.sleep(3) ###### not receiver, sender should sleep #######
                        return True
            else:
                # time.sleep(3) ###### not receiver, sender should sleep #######
                return False
        else:
            print(f"Node {self.node_id}: Collision detected. Not sending CTS.")
            return False

    def send_cts(self, source_id):##sending cts to source_id
        cts_message = self.create_mac_header('01', self.node_id, source_id)
        print(f"Node {self.node_id}: Sending CTS to Node {source_id}. CTS message: {cts_message}")
        send_audio(cts_message)

        return True
       
    def receive_cts(self):##Receive Cts
        final = receive_signal(4)
        if len(final) == 6:
            first_two_bits = final[:2]
            middle_two_bits = final[2:4]
            last_two_bits = final[-2:]

            print(f"Node {self.node_id}: Listening for CTS from Node {int(middle_two_bits,2)}...")

            if first_two_bits == '01':
                last_two_decimal = int(last_two_bits, 2)

                if last_two_decimal == self.node_id:
                    if last_two_decimal != middle_two_bits:
                        print(f"Node {self.node_id}: Received CTS.")
                        return True
            else:
                time.sleep(3)
                return False
        else:
            print(f"Node {self.node_id}: Collision detected. Not received CTS.")
            return False

    def send_data(self, destination_id, message): #Sending message to destination_id
        data_message = self.create_mac_header('10', self.node_id, destination_id, message) ##Used first two bits '10' for detecting the message type
        print(f"Node {self.node_id}: Transmitting data '{message}' to Node {destination_id}. Data message: {data_message}")
        send_audio(data_message)

        return True

    def receive_data(self):# Receives data from the node sending rts.
        data_received = receive_signal(8)
        if len(data_received) > 8:
            first_two_bits = data_received[:2] #Extracts first two bits
            middle_two_bits = data_received[2:4] #Extracts middle two bits
            source_id = int(middle_two_bits,2) #Extracts node_id of sender
            message = data_received[6:]
            print(f"[RECVD] {message} {source_id} {datetime.now()}")

            if first_two_bits == '10':
                print(f"Node {self.node_id}: Data received from Node {source_id}.")
                # self.send_ack(self,source_id)
                return True
        else:
            print(f"Node {self.node_id}: Wrong Data received. Collision likely occurred.")
            return False

