def sender_thread(node, message_trigger_queue, destination_trigger_queue):
    while True:
        if not message_trigger_queue.empty():
            message = message_trigger_queue.queue[0] ## Taking the first message from the queue
            receiver = destination_trigger_queue.queue[0] ## Taking the first destination from the queue

            if receiver == -1: #No need to send the message
                data = message_trigger_queue.get() #Popping of the message from the queue
                dest = destination_trigger_queue.get() #Popping of the destination from the queue
                continue

            while True:
                if is_channel_busy(): ## Carrier Sensing 
                    print(f"Node {node.node_id}: Channel is busy, waiting...")
                    time.sleep(0.5)
                else:
                    break
               
            if node.send_rts(receiver):
                if not node.receive_cts():
                    backoff_time = random.uniform(1, 5) ## Setting random back-off time
                    print(f"Node {node.node_id}: Backing off for {backoff_time:.2f} seconds.")
                    time.sleep(backoff_time)
                    continue

                node.send_data(receiver, message) # Sending data message to the destination node

                # if not node.receive_ack():
                #     backoff_time = random.uniform(1, 3)
                #     print(f"Node {node.node_id}: No ACK received, backing off for {backoff_time:.2f} seconds.")
                #     time.sleep(backoff_time)
                #     continue

                # else:
                data = message_trigger_queue.get() #popping of the message
                dest = destination_trigger_queue.get()
    # time.sleep(1)

