def input_listener(node, message_trigger_queue, destination_trigger_queue):
    while True:
        input()
        print("Enter pressed inorder to trigger a message sending event...")
        if not node.message_queue.empty(): ## If message queue is not empty
            message = node.message_queue.get()
            destination = node.destination_queue.get()
            print(f"[SENT]: {message} {destination} {datetime.now()}") ## Given trigger and this thread prints out the current time stamp
            message_trigger_queue.put(message)
            destination_trigger_queue.put(destination)

